import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            if (n > m) {
                int t = n;
                n = m;
                m = t;
            }
            long V = (long) n * m;

            if (V < 100) {
                int v = (int) V;
                List<Integer>[] g = new List[v];
                for (int i = 0; i < v; i++) g[i] = new ArrayList<>();
                for (int i = 0; i < v; i++) {
                    int r1 = i / m;
                    int c1 = i % m;
                    if (((r1 + c1) & 1) == 0) {
                        for (int j = 0; j < v; j++) {
                            int r2 = j / m;
                            int c2 = j % m;
                            if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 3) {
                                g[i].add(j);
                            }
                        }
                    }
                }

                int N = 2 + 2 * v;
                List<Edge>[] graph = new List[N];
                for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
                int S = 0;
                int T = 1;

                for (int i = 0; i < v; i++) {
                    int r = i / m;
                    int c = i % m;
                    if (((r + c) & 1) == 0) {
                        addEdge(graph, S, 2 + i, 1);
                        for (int j : g[i]) {
                            addEdge(graph, 2 + i, 2 + v + j, 1);
                        }
                    } else {
                        addEdge(graph, 2 + v + i, T, 1);
                    }
                }

                int flow = maxFlow(graph, S, T);
                out.println(flow * 2);
            } else {
                long res;
                if (n == 1) {
                    res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
                } else {
                    res = V;
                    res -= res % 2;
                }
                out.println(res);
            }
        }

        static class Edge {
            int to, rev, cap;
            Edge(int to, int rev, int cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }

        static void addEdge(List<Edge>[] graph, int from, int to, int cap) {
            graph[from].add(new Edge(to, graph[to].size(), cap));
            graph[to].add(new Edge(from, graph[from].size() - 1, 0));
        }

        static int maxFlow(List<Edge>[] graph, int s, int t) {
            int flow = 0;
            int[] level = new int[graph.length];
            int[] it = new int[graph.length];
            int INF = Integer.MAX_VALUE;

            while (bfsLevel(graph, s, t, level)) {
                Arrays.fill(it, 0);
                while (true) {
                    int f = dfsFlow(graph, s, t, INF, level, it);
                    if (f == 0) break;
                    flow += f;
                }
            }
            return flow;
        }

        static boolean bfsLevel(List<Edge>[] graph, int s, int t, int[] level) {
            Arrays.fill(level, -1);
            Queue<Integer> q = new ArrayDeque<>();
            q.add(s);
            level[s] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : graph[u]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[u] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        static int dfsFlow(List<Edge>[] graph, int u, int t, int f, int[] level, int[] it) {
            if (u == t) return f;
            for (; it[u] < graph[u].size(); it[u]++) {
                Edge e = graph[u].get(it[u]);
                if (e.cap > 0 && level[u] + 1 == level[e.to]) {
                    int d = dfsFlow(graph, e.to, t, Math.min(f, e.cap), level, it);
                    if (d > 0) {
                        e.cap -= d;
                        graph[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1) throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
